415→applybounds(Client *c, struct wlr_box *bbox)
416→{
417→	/* Minimum geometry must fit borders AND titlebars with at least 1px content */
418→	int min_w = 1 + 2 * (int)c->bw
419→		+ c->titlebar[CLIENT_TITLEBAR_LEFT].size
420→		+ c->titlebar[CLIENT_TITLEBAR_RIGHT].size;
421→	int min_h = 1 + 2 * (int)c->bw
422→		+ c->titlebar[CLIENT_TITLEBAR_TOP].size
423→		+ c->titlebar[CLIENT_TITLEBAR_BOTTOM].size;
424→	c->geometry.width = MAX(min_w, c->geometry.width);
425→	c->geometry.height = MAX(min_h, c->geometry.height);
426→
427→	if (c->geometry.x >= bbox->x + bbox->width)
428→		c->geometry.x = bbox->x + bbox->width - c->geometry.width;
429→	if (c->geometry.y >= bbox->y + bbox->height)
430→		c->geometry.y = bbox->y + bbox->height - c->geometry.height;
431→	if (c->geometry.x + c->geometry.width <= bbox->x)
432→		c->geometry.x = bbox->x;
433→	if (c->geometry.y + c->geometry.height <= bbox->y)
434→		c->geometry.y = bbox->y;
435→}
