 71→		surface->set_geometry.notify = unmanaged_handle_set_geometry;
 72→	}
 73→
 74→	if (wlr_xwayland_surface_override_redirect_wants_focus(xsurface)) {
 75→		struct sway_seat *seat = input_manager_current_seat();
 76→		struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
 77→		wlr_xwayland_set_seat(xwayland, seat->wlr_seat);
 78→		seat_set_focus_surface(seat, xsurface->surface, false);
