551→static void handle_override_redirect(struct wl_listener *listener, void *data) {
552→	struct sway_xwayland_view *xwayland_view =
553→		wl_container_of(listener, xwayland_view, override_redirect);
554→	struct sway_view *view = &xwayland_view->view;
555→	struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
556→
557→	bool associated = xsurface->surface != NULL;
558→	bool mapped = associated && xsurface->surface->mapped;
559→	if (mapped) {
560→		handle_unmap(&xwayland_view->unmap, NULL);
561→	}
562→	if (associated) {
563→		handle_dissociate(&xwayland_view->dissociate, NULL);
564→	}
565→
566→	handle_destroy(&xwayland_view->destroy, view);
567→	xsurface->data = NULL;
568→
569→	struct sway_xwayland_unmanaged *unmanaged = create_unmanaged(xsurface);
570→	if (associated) {
571→		unmanaged_handle_associate(&unmanaged->associate, NULL);
572→	}
573→	if (mapped) {
574→		unmanaged_handle_map(&unmanaged->map, xsurface);
575→	}
576→}
