578→static void handle_request_configure(struct wl_listener *listener, void *data) {
579→	struct sway_xwayland_view *xwayland_view =
580→		wl_container_of(listener, xwayland_view, request_configure);
581→	struct wlr_xwayland_surface_configure_event *ev = data;
582→	struct sway_view *view = &xwayland_view->view;
583→	struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
584→	if (xsurface->surface == NULL || !xsurface->surface->mapped) {
585→		wlr_xwayland_surface_configure(xsurface, ev->x, ev->y,
586→			ev->width, ev->height);
587→		return;
588→	}
589→	if (container_is_floating(view->container)) {
590→		// Respect minimum and maximum sizes
591→		view->natural_width = ev->width;
592→		view->natural_height = ev->height;
593→		container_floating_resize_and_center(view->container);
594→
595→		configure(view, view->container->pending.content_x,
596→				view->container->pending.content_y,
597→				view->container->pending.content_width,
598→				view->container->pending.content_height);
599→		node_set_dirty(&view->container->node);
600→	} else {
601→		configure(view, view->container->current.content_x,
602→				view->container->current.content_y,
603→				view->container->current.content_width,
604→				view->container->current.content_height);
605→	}
606→}
