799→struct sway_xwayland_view *create_xwayland_view(struct wlr_xwayland_surface *xsurface) {
800→	sway_log(SWAY_DEBUG, "New xwayland surface title='%s' class='%s'",
801→		xsurface->title, xsurface->class);
802→
803→	struct sway_xwayland_view *xwayland_view =
804→		calloc(1, sizeof(struct sway_xwayland_view));
805→	if (!sway_assert(xwayland_view, "Failed to allocate view")) {
806→		return NULL;
807→	}
808→
809→	if (!view_init(&xwayland_view->view, SWAY_VIEW_XWAYLAND, &view_impl)) {
810→		free(xwayland_view);
811→		return NULL;
812→	}
813→	xwayland_view->view.wlr_xwayland_surface = xsurface;
814→
815→	wl_signal_add(&xsurface->events.destroy, &xwayland_view->destroy);
816→	xwayland_view->destroy.notify = handle_destroy;
817→
818→	wl_signal_add(&xsurface->events.request_configure,
819→		&xwayland_view->request_configure);
820→	xwayland_view->request_configure.notify = handle_request_configure;
821→
822→	wl_signal_add(&xsurface->events.request_fullscreen,
823→		&xwayland_view->request_fullscreen);
824→	xwayland_view->request_fullscreen.notify = handle_request_fullscreen;
825→
826→	wl_signal_add(&xsurface->events.request_minimize,
827→		&xwayland_view->request_minimize);
828→	xwayland_view->request_minimize.notify = handle_request_minimize;
829→
830→	wl_signal_add(&xsurface->events.request_activate,
831→		&xwayland_view->request_activate);
832→	xwayland_view->request_activate.notify = handle_request_activate;
833→
834→	wl_signal_add(&xsurface->events.request_move,
835→		&xwayland_view->request_move);
836→	xwayland_view->request_move.notify = handle_request_move;
837→
838→	wl_signal_add(&xsurface->events.request_resize,
839→		&xwayland_view->request_resize);
840→	xwayland_view->request_resize.notify = handle_request_resize;
841→
842→	wl_signal_add(&xsurface->events.set_title, &xwayland_view->set_title);
843→	xwayland_view->set_title.notify = handle_set_title;
844→
845→	wl_signal_add(&xsurface->events.set_class, &xwayland_view->set_class);
846→	xwayland_view->set_class.notify = handle_set_class;
847→
848→	wl_signal_add(&xsurface->events.set_role, &xwayland_view->set_role);
849→	xwayland_view->set_role.notify = handle_set_role;
850→
851→	wl_signal_add(&xsurface->events.set_startup_id,
852→			&xwayland_view->set_startup_id);
853→	xwayland_view->set_startup_id.notify = handle_set_startup_id;
854→
855→	wl_signal_add(&xsurface->events.set_window_type,
856→			&xwayland_view->set_window_type);
857→	xwayland_view->set_window_type.notify = handle_set_window_type;
858→
859→	wl_signal_add(&xsurface->events.set_hints, &xwayland_view->set_hints);
860→	xwayland_view->set_hints.notify = handle_set_hints;
861→
862→	wl_signal_add(&xsurface->events.set_decorations,
863→			&xwayland_view->set_decorations);
864→	xwayland_view->set_decorations.notify = handle_set_decorations;
865→
866→	wl_signal_add(&xsurface->events.associate, &xwayland_view->associate);
867→	xwayland_view->associate.notify = handle_associate;
868→
869→	wl_signal_add(&xsurface->events.dissociate, &xwayland_view->dissociate);
870→	xwayland_view->dissociate.notify = handle_dissociate;
871→
872→	wl_signal_add(&xsurface->events.set_override_redirect,
873→			&xwayland_view->override_redirect);
874→	xwayland_view->override_redirect.notify = handle_override_redirect;
875→
876→	xsurface->data = xwayland_view;
877→
878→	return xwayland_view;
879→}
