893→void handle_xwayland_ready(struct wl_listener *listener, void *data) {
894→	struct sway_server *server =
895→		wl_container_of(listener, server, xwayland_ready);
896→	struct sway_xwayland *xwayland = &server->xwayland;
897→
898→	xcb_connection_t *xcb_conn = xcb_connect(NULL, NULL);
899→	int err = xcb_connection_has_error(xcb_conn);
900→	if (err) {
901→		sway_log(SWAY_ERROR, "XCB connect failed: %d", err);
902→		return;
903→	}
904→
905→	xcb_intern_atom_cookie_t cookies[ATOM_LAST];
906→	for (size_t i = 0; i < ATOM_LAST; i++) {
907→		cookies[i] =
908→			xcb_intern_atom(xcb_conn, 0, strlen(atom_map[i]), atom_map[i]);
909→	}
910→	for (size_t i = 0; i < ATOM_LAST; i++) {
911→		xcb_generic_error_t *error = NULL;
912→		xcb_intern_atom_reply_t *reply =
913→			xcb_intern_atom_reply(xcb_conn, cookies[i], &error);
914→		if (reply != NULL && error == NULL) {
915→			xwayland->atoms[i] = reply->atom;
916→		}
917→		free(reply);
918→
919→		if (error != NULL) {
920→			sway_log(SWAY_ERROR, "could not resolve atom %s, X11 error code %d",
921→				atom_map[i], error->error_code);
922→			free(error);
923→			break;
924→		}
925→	}
926→
927→	xcb_disconnect(xcb_conn);
928→}
