 986→void view_center_and_clip_surface(struct sway_view *view) {
 987→	struct sway_container *con = view->container;
 988→
 989→	bool clip_to_geometry = true;
 990→
 991→	if (container_is_floating(con)) {
 992→		// We always center the current coordinates rather than the next, as the
 993→		// geometry immediately affects the currently active rendering.
 994→		int x = (int) fmax(0, (con->current.content_width - view->geometry.width) / 2);
 995→		int y = (int) fmax(0, (con->current.content_height - view->geometry.height) / 2);
 996→		clip_to_geometry = !view->using_csd;
 997→
 998→		wlr_scene_node_set_position(&view->content_tree->node, x, y);
 999→	} else {
1000→		wlr_scene_node_set_position(&view->content_tree->node, 0, 0);
1001→	}
1002→
1003→	// only make sure to clip the content if there is content to clip
1004→	if (!wl_list_empty(&con->view->content_tree->children)) {
1005→		struct wlr_box clip = {0};
1006→		if (clip_to_geometry) {
1007→			clip = (struct wlr_box){
1008→				.x = con->view->geometry.x,
1009→				.y = con->view->geometry.y,
1010→				.width = con->current.content_width,
1011→				.height = con->current.content_height,
1012→			};
1013→		}
1014→		wlr_scene_subsurface_tree_set_clip(&con->view->content_tree->node, &clip);
1015→	}
