 15→static void apply_horiz_layout(list_t *children, struct wlr_box *parent) {
 16→	if (!children->length) {
 17→		return;
 18→	}
 19→
 20→	// Count the number of new windows we are resizing, and how much space
 21→	// is currently occupied
 22→	int new_children = 0;
 23→	double current_width_fraction = 0;
 24→	for (int i = 0; i < children->length; ++i) {
 25→		struct sway_container *child = children->items[i];
 26→		current_width_fraction += child->width_fraction;
 27→		if (child->width_fraction <= 0) {
 28→			new_children += 1;
 29→		}
 30→	}
 31→
 32→	// Calculate each width fraction
 33→	double total_width_fraction = 0;
 34→	for (int i = 0; i < children->length; ++i) {
 35→		struct sway_container *child = children->items[i];
 36→		if (child->width_fraction <= 0) {
 37→			if (current_width_fraction <= 0) {
 38→				child->width_fraction = 1.0;
 39→			} else if (children->length > new_children) {
 40→				child->width_fraction = current_width_fraction /
 41→					(children->length - new_children);
 42→			} else {
 43→				child->width_fraction = current_width_fraction;
 44→			}
 45→		}
 46→		total_width_fraction += child->width_fraction;
 47→	}
 48→	// Normalize width fractions so the sum is 1.0
 49→	for (int i = 0; i < children->length; ++i) {
 50→		struct sway_container *child = children->items[i];
 51→		child->width_fraction /= total_width_fraction;
 52→	}
 53→
 54→	// Calculate gap size
 55→	double inner_gap = 0;
 56→	struct sway_container *child = children->items[0];
 57→	struct sway_workspace *ws = child->pending.workspace;
 58→	if (ws) {
 59→		inner_gap = ws->gaps_inner;
 60→	}
 61→	// Descendants of tabbed/stacked containers don't have gaps
 62→	struct sway_container *temp = child;
 63→	while (temp) {
 64→		enum sway_container_layout layout = container_parent_layout(temp);
 65→		if (layout == L_TABBED || layout == L_STACKED) {
 66→			inner_gap = 0;
 67→		}
 68→		temp = temp->pending.parent;
 69→	}
 70→	double total_gap = fmin(inner_gap * (children->length - 1),
 71→		fmax(0, parent->width - MIN_SANE_W * children->length));
 72→	double child_total_width = parent->width - total_gap;
 73→	inner_gap = floor(total_gap / (children->length - 1));
 74→
 75→	// Resize windows
 76→	sway_log(SWAY_DEBUG, "Arranging %p horizontally", parent);
 77→	double child_x = parent->x;
 78→	for (int i = 0; i < children->length; ++i) {
 79→		struct sway_container *child = children->items[i];
 80→		child->child_total_width = child_total_width;
 81→		child->pending.x = child_x;
 82→		child->pending.y = parent->y;
 83→		child->pending.width = round(child->width_fraction * child_total_width);
 84→		child->pending.height = parent->height;
 85→
 86→		// Make last child use remaining width of parent
 87→		if (i == children->length - 1) {
 88→			child->pending.width = parent->x + parent->width - child->pending.x;
 89→		}
 90→
 91→		// Arbitrary lower bound for window size
 92→		if (child->pending.width < 10 || child->pending.height < 10) {
 93→			child->pending.width = 0;
 94→			child->pending.height = 0;
 95→		}
 96→		child_x += child->pending.width + inner_gap;
 97→	}
 98→}
