100→static void apply_vert_layout(list_t *children, struct wlr_box *parent) {
101→	if (!children->length) {
102→		return;
103→	}
104→
105→	// Count the number of new windows we are resizing, and how much space
106→	// is currently occupied
107→	int new_children = 0;
108→	double current_height_fraction = 0;
109→	for (int i = 0; i < children->length; ++i) {
110→		struct sway_container *child = children->items[i];
111→		current_height_fraction += child->height_fraction;
112→		if (child->height_fraction <= 0) {
113→			new_children += 1;
114→		}
115→	}
116→
117→	// Calculate each height fraction
118→	double total_height_fraction = 0;
119→	for (int i = 0; i < children->length; ++i) {
120→		struct sway_container *child = children->items[i];
121→		if (child->height_fraction <= 0) {
122→			if (current_height_fraction <= 0) {
123→				child->height_fraction = 1.0;
124→			} else if (children->length > new_children) {
125→				child->height_fraction = current_height_fraction /
126→					(children->length - new_children);
127→			} else {
128→				child->height_fraction = current_height_fraction;
129→			}
130→		}
131→		total_height_fraction += child->height_fraction;
132→	}
133→	// Normalize height fractions so the sum is 1.0
134→	for (int i = 0; i < children->length; ++i) {
135→		struct sway_container *child = children->items[i];
136→		child->height_fraction /= total_height_fraction;
137→	}
138→
139→	// Calculate gap size
140→	double inner_gap = 0;
141→	struct sway_container *child = children->items[0];
142→	struct sway_workspace *ws = child->pending.workspace;
143→	if (ws) {
144→		inner_gap = ws->gaps_inner;
145→	}
146→	// Descendants of tabbed/stacked containers don't have gaps
147→	struct sway_container *temp = child;
148→	while (temp) {
149→		enum sway_container_layout layout = container_parent_layout(temp);
150→		if (layout == L_TABBED || layout == L_STACKED) {
151→			inner_gap = 0;
152→		}
153→		temp = temp->pending.parent;
154→	}
155→	double total_gap = fmin(inner_gap * (children->length - 1),
156→		fmax(0, parent->height - MIN_SANE_H * children->length));
157→	double child_total_height = parent->height - total_gap;
158→	inner_gap = floor(total_gap / (children->length - 1));
159→
160→	// Resize windows
161→	sway_log(SWAY_DEBUG, "Arranging %p vertically", parent);
162→	double child_y = parent->y;
163→	for (int i = 0; i < children->length; ++i) {
164→		struct sway_container *child = children->items[i];
165→		child->child_total_height = child_total_height;
166→		child->pending.x = parent->x;
167→		child->pending.y = child_y;
168→		child->pending.width = parent->width;
169→		child->pending.height = round(child->height_fraction * child_total_height);
170→
171→		// Make last child use remaining height of parent
172→		if (i == children->length - 1) {
173→			child->pending.height = parent->y + parent->height - child->pending.y;
174→		}
175→
176→		// Arbitrary lower bound for window size
177→		if (child->pending.width < 10 || child->pending.height < 10) {
178→			child->pending.width = 0;
179→			child->pending.height = 0;
180→		}
181→		child_y += child->pending.height + inner_gap;
182→	}
183→}
