185→static void apply_tabbed_layout(list_t *children, struct wlr_box *parent) {
186→	if (!children->length) {
187→		return;
188→	}
189→	for (int i = 0; i < children->length; ++i) {
190→		struct sway_container *child = children->items[i];
191→		int parent_offset = child->view ? 0 : container_titlebar_height();
192→		child->pending.x = parent->x;
193→		child->pending.y = parent->y + parent_offset;
194→		child->pending.width = parent->width;
195→		child->pending.height = parent->height - parent_offset;
196→	}
