221→static void arrange_children(list_t *children,
222→		enum sway_container_layout layout, struct wlr_box *parent) {
223→	// Calculate x, y, width and height of children
224→	switch (layout) {
225→	case L_HORIZ:
226→		apply_horiz_layout(children, parent);
227→		break;
228→	case L_VERT:
229→		apply_vert_layout(children, parent);
230→		break;
231→	case L_TABBED:
232→		apply_tabbed_layout(children, parent);
233→		break;
234→	case L_STACKED:
235→		apply_stacked_layout(children, parent);
236→		break;
237→	case L_NONE:
238→		apply_horiz_layout(children, parent);
239→		break;
240→	}
241→
242→	// Recurse into child containers
243→	for (int i = 0; i < children->length; ++i) {
244→		struct sway_container *child = children->items[i];
245→		arrange_container(child);
246→	}
