264→void arrange_workspace(struct sway_workspace *workspace) {
265→	if (config->reloading) {
266→		return;
267→	}
268→	if (!workspace->output) {
269→		// Happens when there are no outputs connected
270→		return;
271→	}
272→	struct sway_output *output = workspace->output;
273→	struct wlr_box *area = &output->usable_area;
274→	sway_log(SWAY_DEBUG, "Usable area for ws: %dx%d@%d,%d",
275→			area->width, area->height, area->x, area->y);
276→
277→	bool first_arrange = workspace->width == 0 && workspace->height == 0;
278→	struct wlr_box prev_box;
279→	workspace_get_box(workspace, &prev_box);
280→
281→	double prev_x = workspace->x - workspace->current_gaps.left;
282→	double prev_y = workspace->y - workspace->current_gaps.top;
283→	workspace->width = area->width;
284→	workspace->height = area->height;
285→	workspace->x = output->lx + area->x;
286→	workspace->y = output->ly + area->y;
287→
288→	// Adjust any floating containers
289→	double diff_x = workspace->x - prev_x;
290→	double diff_y = workspace->y - prev_y;
291→	if (!first_arrange && (diff_x != 0 || diff_y != 0)) {
292→		for (int i = 0; i < workspace->floating->length; ++i) {
293→			struct sway_container *floater = workspace->floating->items[i];
294→			struct wlr_box workspace_box;
295→			workspace_get_box(workspace, &workspace_box);
296→			floating_fix_coordinates(floater, &prev_box, &workspace_box);
297→			// Set transformation for scratchpad windows.
298→			if (floater->scratchpad) {
299→				struct wlr_box output_box;
300→				output_get_box(output, &output_box);
301→				floater->transform = output_box;
302→			}
303→		}
304→	}
305→
306→	workspace_add_gaps(workspace);
307→	node_set_dirty(&workspace->node);
308→	sway_log(SWAY_DEBUG, "Arranging workspace '%s' at %f, %f", workspace->name,
309→			workspace->x, workspace->y);
310→	if (workspace->fullscreen) {
311→		struct sway_container *fs = workspace->fullscreen;
312→		fs->pending.x = output->lx;
313→		fs->pending.y = output->ly;
314→		fs->pending.width = output->width;
315→		fs->pending.height = output->height;
316→		arrange_container(fs);
317→	} else {
318→		struct wlr_box box;
319→		workspace_get_box(workspace, &box);
320→		arrange_children(workspace->tiling, workspace->layout, &box);
321→		arrange_floating(workspace->floating);
322→	}
323→}
