325→void arrange_output(struct sway_output *output) {
326→	if (config->reloading) {
327→		return;
328→	}
329→	if (!output->wlr_output->enabled) {
330→		return;
331→	}
332→	for (int i = 0; i < output->workspaces->length; ++i) {
333→		struct sway_workspace *workspace = output->workspaces->items[i];
334→		arrange_workspace(workspace);
335→	}
336→}
