338→void arrange_root(void) {
339→	if (config->reloading) {
340→		return;
341→	}
342→	struct wlr_box layout_box;
343→	wlr_output_layout_get_box(root->output_layout, NULL, &layout_box);
344→	root->x = layout_box.x;
345→	root->y = layout_box.y;
346→	root->width = layout_box.width;
347→	root->height = layout_box.height;
348→
349→	if (root->fullscreen_global) {
350→		struct sway_container *fs = root->fullscreen_global;
351→		fs->pending.x = root->x;
352→		fs->pending.y = root->y;
353→		fs->pending.width = root->width;
354→		fs->pending.height = root->height;
355→		arrange_container(fs);
356→	} else {
357→		for (int i = 0; i < root->outputs->length; ++i) {
358→			struct sway_output *output = root->outputs->items[i];
359→			arrange_output(output);
360→		}
361→	}
362→}
