364→void arrange_node(struct sway_node *node) {
365→	switch (node->type) {
366→	case N_ROOT:
367→		arrange_root();
368→		break;
369→	case N_OUTPUT:
370→		arrange_output(node->sway_output);
371→		break;
372→	case N_WORKSPACE:
373→		arrange_workspace(node->sway_workspace);
374→		break;
375→	case N_CONTAINER:
376→		arrange_container(node->sway_container);
377→		break;
378→	}
379→}
