302→void view_autoconfigure(struct sway_view *view) {
303→	struct sway_container *con = view->container;
304→	struct sway_workspace *ws = con->pending.workspace;
305→
306→	if (container_is_scratchpad_hidden(con) &&
307→			con->pending.fullscreen_mode != FULLSCREEN_GLOBAL) {
308→		return;
309→	}
310→	struct sway_output *output = ws ? ws->output : NULL;
311→
312→	if (output && con->pending.fullscreen_mode == FULLSCREEN_WORKSPACE) {
313→		con->pending.content_x = output->lx;
314→		con->pending.content_y = output->ly;
315→		con->pending.content_width = output->width;
316→		con->pending.content_height = output->height;
317→		return;
318→	} else if (con->pending.fullscreen_mode == FULLSCREEN_GLOBAL) {
319→		con->pending.content_x = root->x;
320→		con->pending.content_y = root->y;
321→		con->pending.content_width = root->width;
322→		con->pending.content_height = root->height;
323→		return;
324→	}
325→
326→	con->pending.border_top = con->pending.border_bottom = true;
327→	con->pending.border_left = con->pending.border_right = true;
328→	double y_offset = 0;
329→
330→	if (!container_is_floating_or_child(con) && ws) {
331→		if (config->hide_edge_borders == E_BOTH
332→				|| config->hide_edge_borders == E_VERTICAL) {
333→			con->pending.border_left = con->pending.x != ws->x;
334→			int right_x = con->pending.x + con->pending.width;
335→			con->pending.border_right = right_x != ws->x + ws->width;
336→		}
337→
338→		if (config->hide_edge_borders == E_BOTH
339→				|| config->hide_edge_borders == E_HORIZONTAL) {
340→			con->pending.border_top = con->pending.y != ws->y;
341→			int bottom_y = con->pending.y + con->pending.height;
342→			con->pending.border_bottom = bottom_y != ws->y + ws->height;
343→		}
344→
345→		bool smart = config->hide_edge_borders_smart == ESMART_ON ||
346→			(config->hide_edge_borders_smart == ESMART_NO_GAPS &&
347→			!gaps_to_edge(view));
348→		if (smart) {
349→			bool show_border = !view_is_only_visible(view);
350→			con->pending.border_left &= show_border;
351→			con->pending.border_right &= show_border;
352→			con->pending.border_top &= show_border;
353→			con->pending.border_bottom &= show_border;
354→		}
355→	}
356→
357→	if (!container_is_floating(con)) {
358→		// In a tabbed or stacked container, the container's y is the top of the
359→		// title area. We have to offset the surface y by the height of the title,
360→		// bar, and disable any top border because we'll always have the title bar.
361→		list_t *siblings = container_get_siblings(con);
362→		bool show_titlebar = (siblings && siblings->length > 1)
363→			|| !config->hide_lone_tab;
364→		if (show_titlebar) {
365→			enum sway_container_layout layout = container_parent_layout(con);
366→			if (layout == L_TABBED) {
367→				y_offset = container_titlebar_height();
368→				con->pending.border_top = false;
369→			} else if (layout == L_STACKED) {
370→				y_offset = container_titlebar_height() * siblings->length;
371→				con->pending.border_top = false;
372→			}
373→		}
374→	}
375→
376→	double x, y, width, height;
377→	switch (con->pending.border) {
378→	default:
379→	case B_CSD:
380→	case B_NONE:
381→		x = con->pending.x;
382→		y = con->pending.y + y_offset;
383→		width = con->pending.width;
384→		height = con->pending.height - y_offset;
385→		break;
386→	case B_PIXEL:
387→		x = con->pending.x + con->pending.border_thickness * con->pending.border_left;
388→		y = con->pending.y + con->pending.border_thickness * con->pending.border_top + y_offset;
389→		width = con->pending.width
390→			- con->pending.border_thickness * con->pending.border_left
391→			- con->pending.border_thickness * con->pending.border_right;
392→		height = con->pending.height - y_offset
393→			- con->pending.border_thickness * con->pending.border_top
394→			- con->pending.border_thickness * con->pending.border_bottom;
395→		break;
396→	case B_NORMAL:
397→		// Height is: 1px border + 3px pad + title height + 3px pad + 1px border
398→		x = con->pending.x + con->pending.border_thickness * con->pending.border_left;
399→		width = con->pending.width
400→			- con->pending.border_thickness * con->pending.border_left
401→			- con->pending.border_thickness * con->pending.border_right;
402→		if (y_offset) {
403→			y = con->pending.y + y_offset;
404→			height = con->pending.height - y_offset
405→				- con->pending.border_thickness * con->pending.border_bottom;
406→		} else {
407→			y = con->pending.y + container_titlebar_height();
408→			height = con->pending.height - container_titlebar_height()
409→				- con->pending.border_thickness * con->pending.border_bottom;
410→		}
411→		break;
412→	}
413→
414→	con->pending.content_x = x;
415→	con->pending.content_y = y;
416→	con->pending.content_width = fmax(width, 1);
417→	con->pending.content_height = fmax(height, 1);
418→}
