 21→struct sway_transaction {
 22→	struct wl_event_source *timer;
 23→	list_t *instructions;   // struct sway_transaction_instruction *
 24→	size_t num_waiting;
 25→	size_t num_configures;
 26→	struct timespec commit_time;
 27→};
 28→
 29→struct sway_transaction_instruction {
 30→	struct sway_transaction *transaction;
 31→	struct sway_node *node;
 32→	union {
 33→		struct sway_output_state output_state;
 34→		struct sway_workspace_state workspace_state;
 35→		struct sway_container_state container_state;
 36→	};
 37→	uint32_t serial;
 38→	bool server_request;
 39→	bool waiting;
 40→};
