 42→static struct sway_transaction *transaction_create(void) {
 43→	struct sway_transaction *transaction =
 44→		calloc(1, sizeof(struct sway_transaction));
 45→	if (!sway_assert(transaction, "Unable to allocate transaction")) {
 46→		return NULL;
 47→	}
 48→	transaction->instructions = create_list();
 49→	return transaction;
 50→}
 51→
 52→static void transaction_destroy(struct sway_transaction *transaction) {
 53→	// Free instructions
 54→	for (int i = 0; i < transaction->instructions->length; ++i) {
 55→		struct sway_transaction_instruction *instruction =
 56→			transaction->instructions->items[i];
 57→		struct sway_node *node = instruction->node;
 58→		node->ntxnrefs--;
 59→		if (node->instruction == instruction) {
 60→			node->instruction = NULL;
 61→		}
 62→		if (node->destroying && node->ntxnrefs == 0) {
 63→			switch (node->type) {
 64→			case N_ROOT:
 65→				sway_assert(false, "Never reached");
 66→				break;
 67→			case N_OUTPUT:
 68→				output_destroy(node->sway_output);
 69→				break;
 70→			case N_WORKSPACE:
 71→				workspace_destroy(node->sway_workspace);
 72→				break;
 73→			case N_CONTAINER:
 74→				container_destroy(node->sway_container);
 75→				break;
 76→			}
 77→		}
 78→		free(instruction);
 79→	}
 80→	list_free(transaction->instructions);
 81→
 82→	if (transaction->timer) {
 83→		wl_event_source_remove(transaction->timer);
 84→	}
 85→	free(transaction);
 86→}
