 88→static void copy_output_state(struct sway_output *output,
 89→		struct sway_transaction_instruction *instruction) {
 90→	struct sway_output_state *state = &instruction->output_state;
 91→	if (state->workspaces) {
 92→		state->workspaces->length = 0;
 93→	} else {
 94→		state->workspaces = create_list();
 95→	}
 96→	list_cat(state->workspaces, output->workspaces);
 97→
 98→	state->active_workspace = output_get_active_workspace(output);
 99→}
