101→static void copy_workspace_state(struct sway_workspace *ws,
102→		struct sway_transaction_instruction *instruction) {
103→	struct sway_workspace_state *state = &instruction->workspace_state;
104→
105→	state->fullscreen = ws->fullscreen;
106→	state->x = ws->x;
107→	state->y = ws->y;
108→	state->width = ws->width;
109→	state->height = ws->height;
110→	state->layout = ws->layout;
111→
112→	state->output = ws->output;
113→	if (state->floating) {
114→		state->floating->length = 0;
115→	} else {
116→		state->floating = create_list();
117→	}
118→	if (state->tiling) {
119→		state->tiling->length = 0;
120→	} else {
121→		state->tiling = create_list();
122→	}
123→	list_cat(state->floating, ws->floating);
124→	list_cat(state->tiling, ws->tiling);
125→
126→	struct sway_seat *seat = input_manager_current_seat();
127→	state->focused = seat_get_focus(seat) == &ws->node;
128→
129→	// Set focused_inactive_child to the direct tiling child
130→	struct sway_container *focus = seat_get_focus_inactive_tiling(seat, ws);
131→	if (focus) {
132→		while (focus->pending.parent) {
133→			focus = focus->pending.parent;
134→		}
135→	}
136→	state->focused_inactive_child = focus;
137→}
