139→static void copy_container_state(struct sway_container *container,
140→		struct sway_transaction_instruction *instruction) {
141→	struct sway_container_state *state = &instruction->container_state;
142→
143→	if (state->children) {
144→		list_free(state->children);
145→	}
146→
147→	memcpy(state, &container->pending, sizeof(struct sway_container_state));
148→
149→	if (!container->view) {
150→		// We store a copy of the child list to avoid having it mutated after
151→		// we copy the state.
152→		state->children = create_list();
153→		list_cat(state->children, container->pending.children);
154→	} else {
155→		state->children = NULL;
156→	}
157→
158→	struct sway_seat *seat = input_manager_current_seat();
159→	state->focused = seat_get_focus(seat) == &container->node;
160→
161→	if (!container->view) {
162→		struct sway_node *focus =
163→			seat_get_active_tiling_child(seat, &container->node);
164→		state->focused_inactive_child = focus ? focus->sway_container : NULL;
165→	}
166→}
