168→static void transaction_add_node(struct sway_transaction *transaction,
169→		struct sway_node *node, bool server_request) {
170→	struct sway_transaction_instruction *instruction = NULL;
171→
172→	// Check if we have an instruction for this node already, in which case we
173→	// update that instead of creating a new one.
174→	if (node->ntxnrefs > 0) {
175→		for (int idx = 0; idx < transaction->instructions->length; idx++) {
176→			struct sway_transaction_instruction *other =
177→				transaction->instructions->items[idx];
178→			if (other->node == node) {
179→				instruction = other;
180→				break;
181→			}
182→		}
183→	}
184→
185→	if (!instruction) {
186→		instruction = calloc(1, sizeof(struct sway_transaction_instruction));
187→		if (!sway_assert(instruction, "Unable to allocate instruction")) {
188→			return;
189→		}
190→		instruction->transaction = transaction;
191→		instruction->node = node;
192→		instruction->server_request = server_request;
193→
194→		list_add(transaction->instructions, instruction);
195→		node->ntxnrefs++;
196→	} else if (server_request) {
197→		instruction->server_request = true;
198→	}
199→
200→	switch (node->type) {

200→	switch (node->type) {
201→	case N_ROOT:
202→		break;
203→	case N_OUTPUT:
204→		copy_output_state(node->sway_output, instruction);
205→		break;
206→	case N_WORKSPACE:
207→		copy_workspace_state(node->sway_workspace, instruction);
208→		break;
209→	case N_CONTAINER:
210→		copy_container_state(node->sway_container, instruction);
211→		break;
212→	}
213→}
