228→static void apply_container_state(struct sway_container *container,
229→		struct sway_container_state *state) {
230→	struct sway_view *view = container->view;
231→	// There are separate children lists for each instruction state, the
232→	// container's current state and the container's pending state
233→	// (ie. con->children). The list itself needs to be freed here.
234→	// Any child containers which are being deleted will be cleaned up in
235→	// transaction_destroy().
236→	list_free(container->current.children);
237→
238→	memcpy(&container->current, state, sizeof(struct sway_container_state));
239→
240→	if (view) {
241→		if (view->saved_surface_tree) {
242→			if (!container->node.destroying || container->node.ntxnrefs == 1) {
243→				view_remove_saved_buffer(view);
244→			}
245→		}
246→
247→		// If the view hasn't responded to the configure, center it within
248→		// the container. This is important for fullscreen views which
249→		// refuse to resize to the size of the output.
250→		if (view->surface) {
251→			view_center_and_clip_surface(view);
252→		}
253→	}
254→}
