820→static void transaction_commit(struct sway_transaction *transaction) {
821→	sway_log(SWAY_DEBUG, "Transaction %p committing with %i instructions",
822→			transaction, transaction->instructions->length);
823→	transaction->num_waiting = 0;
824→	for (int i = 0; i < transaction->instructions->length; ++i) {
825→		struct sway_transaction_instruction *instruction =
826→			transaction->instructions->items[i];
827→		struct sway_node *node = instruction->node;
828→		bool hidden = node_is_view(node) && !node->destroying &&
829→			!view_is_visible(node->sway_container->view);
830→		if (should_configure(node, instruction)) {
831→			instruction->serial = view_configure(node->sway_container->view,
832→					instruction->container_state.content_x,
833→					instruction->container_state.content_y,
834→					instruction->container_state.content_width,
835→					instruction->container_state.content_height);
836→			if (!hidden) {
837→				instruction->waiting = true;
838→				++transaction->num_waiting;
839→			}
840→
841→			view_send_frame_done(node->sway_container->view);
842→		}
843→		if (!hidden && node_is_view(node) &&
844→				!node->sway_container->view->saved_surface_tree) {
845→			view_save_buffer(node->sway_container->view);
846→		}
847→		node->instruction = instruction;
848→	}
849→	transaction->num_configures = transaction->num_waiting;
850→	if (debug.txn_timings) {
851→		clock_gettime(CLOCK_MONOTONIC, &transaction->commit_time);
852→	}
853→	if (debug.noatomic) {
854→		transaction->num_waiting = 0;
855→	} else if (debug.txn_wait) {
856→		// Force the transaction to time out even if all views are ready.
857→		// We do this by inflating the waiting counter.
858→		transaction->num_waiting += 1000000;
859→	}
860→
861→	if (transaction->num_waiting) {
862→		// Set up a timer which the views must respond within
863→		transaction->timer = wl_event_loop_add_timer(server.wl_event_loop,
864→				handle_timeout, transaction);
865→		if (transaction->timer) {
866→			wl_event_source_timer_update(transaction->timer,
867→					server.txn_timeout_ms);
868→		} else {
869→			sway_log_errno(SWAY_ERROR, "Unable to create transaction timer "
870→					"(some imperfect frames might be rendered)");
871→			transaction->num_waiting = 0;
872→		}
873→	}
874→}
