	/* For XWayland clients, always sync position even during pending resize.
	 * X11 clients use their position for popup placement (e.g. Steam menus).
	 * Without this, popups appear at the old position after the window moves.
	 * Position includes titlebar offset since the X11 surface starts after titlebars. */
#ifdef XWAYLAND
	if (client_is_x11(c)) {
		int16_t cx = c->geometry.x + c->bw + titlebar_left;
		int16_t cy = c->geometry.y + c->bw + titlebar_top;
		if (cx != c->surface.xwayland->x || cy != c->surface.xwayland->y) {
			wlr_xwayland_surface_configure(c->surface.xwayland,
					cx, cy,
					c->surface.xwayland->width,
					c->surface.xwayland->height);
		}
	}
#endif

