	/* For XWayland clients, always sync position even during pending resize.
	 * X11 clients use their position for popup placement (e.g. Steam menus).
	 * Without this, popups appear at the old position after the window moves.
	 * Position includes titlebar offset since the X11 surface starts after titlebars. */
#ifdef XWAYLAND
	if (client_is_x11(c)) {
		int16_t cx = c->geometry.x + c->bw + titlebar_left;
		int16_t cy = c->geometry.y + c->bw + titlebar_top;
		if (cx != c->surface.xwayland->x || cy != c->surface.xwayland->y) {
			wlr_xwayland_surface_configure(c->surface.xwayland,
					cx, cy,
					c->surface.xwayland->width,
					c->surface.xwayland->height);
		}
	}
#endif

input.new_string:
	/* For XWayland clients, always sync position even during pending resize.
	 * X11 clients use their position for popup placement (e.g. Steam menus).
	 * Without this, popups appear at the old position after the window moves.
	 * Position includes titlebar offset since the X11 surface starts after titlebars.
	 *
	 * IMPORTANT: We flush XCB immediately after configure to minimize the
	 * timing window between position update and pointer events. Without this,
	 * the deferred xwm_schedule_flush() may deliver the position update AFTER
	 * pointer events reach XWayland, causing popup menus to use stale positions.
	 * No other compositor does this — KDE/Hyprland/Sway all accept the stale
	 * positioning as an XWayland limitation. */
#ifdef XWAYLAND
	if (client_is_x11(c)) {
		int16_t cx = c->geometry.x + c->bw + titlebar_left;
		int16_t cy = c->geometry.y + c->bw + titlebar_top;
		if (cx != c->surface.xwayland->x || cy != c->surface.xwayland->y) {
			wlr_xwayland_surface_configure(c->surface.xwayland,
					cx, cy,
					c->surface.xwayland->width,
					c->surface.xwayland->height);
			xcb_connection_t *xcb_conn = wlr_xwayland_get_xwm_connection(xwayland);
			if (xcb_conn)
				xcb_flush(xcb_conn);
		}
	}
#endif

