	/* For XWayland clients, re-send current position before pointer enter.
	 * Steam/CEF processes ConfigureNotify lazily — by re-sending here, we
	 * ensure a fresh position update is queued in the X server RIGHT BEFORE
	 * the pointer events that trigger popup creation. The immediate
	 * xcb_flush() pushes it to XWayland before the Wayland pointer enter. */
#ifdef XWAYLAND
	if (c && client_is_x11(c) && !client_is_unmanaged(c)) {
		int tl = c->fullscreen ? 0 : c->titlebar[CLIENT_TITLEBAR_LEFT].size;
		int tt = c->fullscreen ? 0 : c->titlebar[CLIENT_TITLEBAR_TOP].size;
		int16_t cx = c->geometry.x + c->bw + tl;
		int16_t cy = c->geometry.y + c->bw + tt;
		wlr_xwayland_surface_configure(c->surface.xwayland,
				cx, cy,
				c->surface.xwayland->width,
				c->surface.xwayland->height);
		xcb_connection_t *xcb_conn = wlr_xwayland_get_xwm_connection(xwayland);
		if (xcb_conn)
			xcb_flush(xcb_conn);
	}
#endif

	/* Deliver pointer enter + motion to the surface.
	 * wlr_seat_pointer_enter is a no-op if surface is already focused AND
	 * the client has pointer resources (normal case). */
	wlr_seat_pointer_notify_enter(seat, surface, sx, sy);
	wlr_seat_pointer_notify_motion(seat, time, sx, sy);

