/* Sway pattern: inform XWayland of the active seat on every focus
 * change to an X11 client. Required for proper keyboard delivery. */
if (c->client_type == X11) {
	wlr_log(WLR_DEBUG, "[FOCUS] calling wlr_xwayland_set_seat");
	wlr_xwayland_set_seat(xwayland, seat);

	/* Sync X11 position on every focus change. X11 clients (Steam/CEF)
	 * may only process ConfigureNotify when they receive focus events.
	 * Without this, popup menus use stale cached positions after the
	 * window has been moved by the tiling layout. */
	if (!client_is_unmanaged(c)) {
		int tl = c->fullscreen ? 0 : c->titlebar[CLIENT_TITLEBAR_LEFT].size;
		int tt = c->fullscreen ? 0 : c->titlebar[CLIENT_TITLEBAR_TOP].size;
		int16_t cx = c->geometry.x + c->bw + tl;
		int16_t cy = c->geometry.y + c->bw + tt;
		wlr_xwayland_surface_configure(c->surface.xwayland,
				cx, cy,
				c->surface.xwayland->width,
				c->surface.xwayland->height);
		xcb_connection_t *xcb_conn = wlr_xwayland_get_xwm_connection(xwayland);
		if (xcb_conn)
			xcb_flush(xcb_conn);
	}
}

