240→static int
241→ipc_handle_client_data(int fd, uint32_t mask, void *data)
242→{
243→	struct ipc_client *client = data;
244→	char *newline;
245→	ssize_t n;
246→
247→	/* Read data */
248→	n = read(client->fd, client->buffer + client->buffer_used,
249→	         client->buffer_size - client->buffer_used - 1);
250→
251→	if (n <= 0) {
252→		/* Connection closed or error */
253→		if (n < 0 && errno != EINTR && errno != EAGAIN) {
254→			fprintf(stderr, "IPC: Client read error: %s\n", strerror(errno));
255→		}
256→		ipc_client_destroy(client);
257→		return 0;
258→	}
259→
260→	client->buffer_used += n;
261→	client->buffer[client->buffer_used] = '\0';
262→
263→	/* Process complete commands (lines ending with \n) */
264→	while ((newline = strchr(client->buffer, '\n')) != NULL) {
265→		size_t command_len = newline - client->buffer;
266→		char *command;
267→
268→		/* Extract command */
269→		command = ecalloc(1, command_len + 1);
270→		memcpy(command, client->buffer, command_len);
271→		command[command_len] = '\0';
272→
273→		/* Process it */
274→		if (command_len > 0) {
275→			ipc_process_command(client, command);
276→		}
277→		free(command);
278→
279→		/* Remove processed command from buffer */
280→		client->buffer_used -= (command_len + 1);
281→		memmove(client->buffer, newline + 1, client->buffer_used + 1);
282→	}
283→
284→	/* Check for buffer overflow */
285→	if (client->buffer_used >= client->buffer_size - 1) {
286→		const char *msg = "ERROR Command too long\n\n";
287→		(void)!write(client->fd, msg, strlen(msg));
288→		ipc_client_destroy(client);
289→		return 0;
290→	}
291→
292→	return 0;
293→}
