295→static void
296→ipc_client_destroy(struct ipc_client *client)
297→{
298→	if (client->event_source) {
299→		wl_event_source_remove(client->event_source);
300→	}
301→
302→	if (client->fd >= 0) {
303→		close(client->fd);
304→	}
305→
306→	wl_list_remove(&client->link);
307→	free(client->buffer);
308→	free(client);
309→}
