311→/**
312→ * Send response to IPC client
313→ * Format: STATUS MESSAGE\n[DATA]\n\n
314→ */
315→void
316→ipc_send_response(int client_fd, const char *response)
317→{
318→	if (client_fd >= 0 && response) {
319→		(void)!write(client_fd, response, strlen(response));
320→		/* Ensure response ends with double newline */
321→		if (!strstr(response + strlen(response) - 2, "\n\n")) {
322→			(void)!write(client_fd, "\n", 1);
323→		}
324→	}
325→}
