16→/**
17→ * Dispatch IPC command to Lua
18→ * Called from C when a complete command is received from the socket.
19→ * Calls the Lua function _ipc_dispatch(command_string, client_fd)
20→ */
21→void
22→ipc_dispatch_to_lua(int client_fd, const char *command)
23→{
24→	lua_State *L = globalconf_L;
25→	const char *result;
26→
27→	if (!L) {
28→		ipc_send_response(client_fd, "ERROR Lua not initialized\n\n");
29→		return;
30→	}
31→
32→	/* Get the _ipc_dispatch function from global scope */
33→	lua_getglobal(L, "_ipc_dispatch");
34→	if (!lua_isfunction(L, -1)) {
35→		lua_pop(L, 1);
36→		ipc_send_response(client_fd, "ERROR IPC dispatcher not initialized\n\n");
37→		return;
38→	}
39→
40→	/* Push arguments: command string and client fd */
41→	lua_pushstring(L, command);
42→	lua_pushinteger(L, client_fd);
43→
44→	/* Call _ipc_dispatch(command, client_fd) */
45→	if (lua_pcall(L, 2, 1, 0) != 0) {
46→		/* Error in Lua code */
47→		const char *error = lua_tostring(L, -1);
48→		char response[1024];
49→		snprintf(response, sizeof(response), "ERROR %s\n\n", error);
50→		ipc_send_response(client_fd, response);
51→		lua_pop(L, 1);
52→		return;
53→	}
54→
55→	/* Get result from Lua (should be a string like "OK\n\n" or "ERROR msg\n\n") */
56→	result = lua_tostring(L, -1);
57→	if (result) {
58→		ipc_send_response(client_fd, result);
59→	} else {
60→		ipc_send_response(client_fd, "ERROR No response from dispatcher\n\n");
61→	}
62→	lua_pop(L, 1);
63→}
