5951→/* Get Lua runtime version string */
5952→static const char *
5953→get_lua_runtime_version(lua_State *L)
5954→{
5955→	static char version[128];
5956→
5957→	/* Check for LuaJIT first */
5958→	lua_getglobal(L, "jit");
5959→	if (lua_istable(L, -1)) {
5960→		lua_getfield(L, -1, "version");
5961→		if (lua_isstring(L, -1)) {
5962→			snprintf(version, sizeof(version), "%s", lua_tostring(L, -1));
5963→			lua_pop(L, 2);
5964→			return version;
5965→		}
5966→		lua_pop(L, 1);
5967→	}
5968→	lua_pop(L, 1);
5969→
5970→	/* Fall back to standard Lua _VERSION */
5971→	lua_getglobal(L, "_VERSION");
5972→	if (lua_isstring(L, -1)) {
5973→		snprintf(version, sizeof(version), "%s", lua_tostring(L, -1));
5974→	} else {
5975→		snprintf(version, sizeof(version), "unknown");
5976→	}
5977→	lua_pop(L, 1);
5978→	return version;
5979→}
