5989→#else
5990→	/* Fallback to runtime detection */
5991→	static char version[64] = "unknown";
5992→
5993→	/* Try: require('lgi.version') */
5994→	if (luaL_dostring(L, "return require('lgi.version')") == 0) {
5995→		if (lua_isstring(L, -1)) {
5996→			snprintf(version, sizeof(version), "%s", lua_tostring(L, -1));
5997→		}
