6004→/* Add search paths to a Lua state's package.path and package.cpath */
6005→static void
6006→add_search_paths_to_lua(lua_State *L, const char **paths, int count)
6007→{
6008→	const char *cur_path;
6009→
6010→	for (int i = 0; i < count; i++) {
6011→		const char *dir = paths[i];
6012→
6013→		/* Add to package.path */
6014→		lua_getglobal(L, "package");
6015→		lua_getfield(L, -1, "path");
6016→		cur_path = lua_tostring(L, -1);
6017→		lua_pop(L, 1);
6018→		lua_pushfstring(L, "%s/?.lua;%s/?/init.lua;%s", dir, dir, cur_path);
6019→		lua_setfield(L, -2, "path");
6020→
6021→		/* Add to package.cpath */
6022→		lua_getfield(L, -1, "cpath");
6023→		cur_path = lua_tostring(L, -1);
6024→		lua_pop(L, 1);
6025→		lua_pushfstring(L, "%s/?.so;%s", dir, cur_path);
6026→		lua_setfield(L, -2, "cpath");
6027→
6028→		lua_pop(L, 1); /* pop package table */
6029→	}
6030→}
