2619→void
2620→handlesig(int signo)
2621→{
2622→	if (signo == SIGCHLD) {
2623→		/* Write to pipe to wake up GLib main loop (AwesomeWM pattern).
2624→		 * Child reaping is done in reap_children() callback. */
2625→		if (sigchld_pipe[1] >= 0) {
2626→			int res = write(sigchld_pipe[1], " ", 1);
2627→			(void) res;  /* Ignore write errors in signal handler */
2628→		}
2629→	} else if (signo == SIGINT || signo == SIGTERM) {
2630→		wl_display_terminate(dpy);
2631→	}
2632→}
