2634→/** GLib callback for SIGCHLD pipe (AwesomeWM pattern).
2635→ * This is called when the SIGCHLD handler writes to the pipe.
2636→ * We read from the pipe and reap all children with waitpid().
2637→ */
2638→static gboolean
2639→reap_children(GIOChannel *channel, GIOCondition condition, gpointer user_data)
2640→{
2641→	pid_t child;
2642→	int status;
2643→	char buffer[1024];
2644→	ssize_t result;
2645→
2646→	/* Read from pipe to clear it */
2647→	result = read(sigchld_pipe[0], buffer, sizeof(buffer));
2648→	if (result < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
2649→		fprintf(stderr, "somewm: error reading from SIGCHLD pipe: %s\n",
2650→		        strerror(errno));
2651→	}
2652→
2653→	/* Reap all exited children */
2654→	while ((child = waitpid(-1, &status, WNOHANG)) > 0) {
2655→		spawn_child_exited(child, status);
2656→	}
2657→
2658→	if (child < 0 && errno != ECHILD) {
2659→		fprintf(stderr, "somewm: waitpid(-1) failed: %s\n", strerror(errno));
2660→	}
2661→
2662→	return TRUE;  /* Keep watching */
2663→}
