4334→	struct wlr_seat_pointer_request_set_cursor_event *event = data;
4335→	/* If we're "grabbing" the cursor, don't use the client's image, we will
4336→	 * restore it after "grabbing" sending a leave event, followed by a enter
4337→	 * event, which will result in the client requesting set the cursor surface */
