4342→	 * use the provided surface as the cursor image. It will set the
4343→	 * hardware cursor on the output that it's currently on and continue to
4344→	 * do so as the cursor moves between outputs. */
4345→	if (event->seat_client == seat->pointer_state.focused_client)
4346→		wlr_cursor_set_surface(cursor, event->surface,
4347→				event->hotspot_x, event->hotspot_y);
4348→}
