4364→/* setfloating() removed - floating state is now managed entirely by Lua property system.
4365→ * Scene graph layer changes happen via arrange() when Lua updates property::floating.
4366→ * This matches AwesomeWM's approach where C doesn't manage floating state. */
4367→
4368→void
4369→setfullscreen(Client *c, int fullscreen)
4370→{
4371→	c->fullscreen = fullscreen;
4372→	if (!c->mon || !client_surface(c)->mapped)
4373→		return;
4374→
4375→	/* Fullscreen is mutually exclusive with maximized states */
4376→	if (fullscreen && (c->maximized || c->maximized_horizontal || c->maximized_vertical)) {
4377→		c->maximized = 0;
4378→		c->maximized_horizontal = 0;
4379→		c->maximized_vertical = 0;
4380→		/* Clear XDG toplevel maximize state if applicable */
4381→		if (c->client_type == XDGShell && c->surface.xdg->toplevel)
4382→			wlr_xdg_toplevel_set_maximized(c->surface.xdg->toplevel, 0);
4383→	}
4384→
4385→	c->bw = fullscreen ? 0 : get_border_width();
4386→	client_set_fullscreen_internal(c, fullscreen);
4387→	wlr_scene_node_reparent(&c->scene->node, layers[c->fullscreen ? LyrFS : LyrTile]);
4388→
4389→	if (fullscreen) {
4390→		c->prev = c->geometry;
4391→		resize(c, c->mon->m, 0);
4392→	} else {
4393→		/* restore previous size instead of arrange for floating windows since
4394→		 * client positions are set by the user and cannot be recalculated */
4395→		resize(c, c->prev, 0);
4396→	}
4397→	arrange(c->mon);
4398→	printstatus();
4399→
4400→	/* Refresh stacking order (fullscreen layer changes) */
4401→	stack_refresh();
4402→
4403→	luaA_emit_signal_global("client::property::fullscreen");
4404→}

