160→	runtime_dir = getenv("XDG_RUNTIME_DIR");
161→	if (!runtime_dir) {
162→		fprintf(stderr, "Error: XDG_RUNTIME_DIR not set\n");
163→		return -1;
164→	}
165→
166→	/* Create socket */
167→	sock = socket(AF_UNIX, SOCK_STREAM, 0);
168→	if (sock < 0) {
169→		perror("socket");
170→		return -1;
171→	}
172→
173→	/* Build address - check for override first */
174→	addr.sun_family = AF_UNIX;
175→	const char *socket_override = getenv("SOMEWM_SOCKET");
176→	if (socket_override && socket_override[0]) {
177→		snprintf(addr.sun_path, sizeof(addr.sun_path), "%s", socket_override);
178→	} else {
179→		snprintf(addr.sun_path, sizeof(addr.sun_path),
180→		         "%s/%s", runtime_dir, SOCKET_NAME);
181→	}
182→
183→	/* Connect */
184→	if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
185→		fprintf(stderr, "Error: Failed to connect to %s\n", addr.sun_path);
186→		fprintf(stderr, "Is somewm running?\n");
187→		perror("connect");
188→		close(sock);
189→		return -1;
190→	}
191→
192→	return sock;
193→}
194→
195→static int
196→send_command(int sock, int argc, char *argv[], int json_mode, int start_arg)
197→{
198→	char command[BUFFER_SIZE];
199→	int offset = 0;
200→	int i;
201→
202→	/* Prepend --json if requested */
203→	if (json_mode) {
204→		offset = snprintf(command, BUFFER_SIZE, "--json ");
205→	}
206→
207→	/* Build command string from argv */
208→	for (i = start_arg; i < argc; i++) {
209→		if (offset > 0 && offset < BUFFER_SIZE - 1 && command[offset - 1] != ' ') {
210→			command[offset++] = ' ';
211→		}
212→		offset += snprintf(command + offset, BUFFER_SIZE - offset - 1,
213→		                   "%s", argv[i]);
214→		if (offset >= BUFFER_SIZE - 1) {
215→			fprintf(stderr, "Error: Command too long\n");
216→			return -1;
217→		}
218→	}
219→
220→	/* Add newline */
221→	if (offset < BUFFER_SIZE - 1) {
222→		command[offset++] = '\n';
223→		command[offset] = '\0';
224→	}
225→
226→	/* Send command */
227→	if (write(sock, command, offset) != offset) {
228→		perror("write");
229→		return -1;
230→	}
231→
232→	return 0;
233→}
234→
235→static int
236→read_response(int sock)
237→{
238→	char buffer[BUFFER_SIZE];
239→	ssize_t n;
240→	int found_end = 0;
241→	int is_error = 0;
242→
243→	/* Read response until we see double newline */
244→	while (!found_end) {
245→		n = read(sock, buffer, sizeof(buffer) - 1);
246→		if (n < 0) {
247→			if (errno == EINTR) {
248→				continue;
249→			}
250→			perror("read");
251→			return -1;
252→		}
253→
254→		if (n == 0) {
255→			/* Connection closed */
256→			break;
257→		}
258→
259→		buffer[n] = '\0';
260→
261→		/* Print response */
262→		printf("%s", buffer);
263→
264→		/* Check for error status */
265→		if (strncmp(buffer, "ERROR", 5) == 0) {
266→			is_error = 1;
267→		}
268→
269→		/* Check for end marker (double newline) */
270→		if (strstr(buffer, "\n\n")) {
271→			found_end = 1;
272→		}
273→	}
274→
275→	return is_error ? 1 : 0;
276→}
277→
278→int
279→main(int argc, char *argv[])
280→{
281→	int sock;
282→	int exit_code;
283→	int json_mode = 0;
284→	int start_arg = 1;
285→
286→	/* Check arguments */
287→	if (argc < 2) {
288→		print_usage(argv[0]);
289→		return 1;
290→	}
291→
292→	/* Handle --help */
293→	if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
294→		print_usage(argv[0]);
295→		return 0;
296→	}
297→
298→	/* Handle --json flag */
299→	if (strcmp(argv[1], "--json") == 0) {
300→		json_mode = 1;
301→		start_arg = 2;
302→		if (argc < 3) {
303→			fprintf(stderr, "Error: --json requires a command\n");
304→			print_usage(argv[0]);
305→			return 1;
306→		}
307→	}
308→
309→	/* Connect to compositor */
310→	sock = connect_to_socket();
311→	if (sock < 0) {
312→		return 2;
313→	}
314→
315→	/* Send command */
316→	if (send_command(sock, argc, argv, json_mode, start_arg) < 0) {
317→		close(sock);
318→		return 1;
319→	}
320→
321→	/* Read and print response */
322→	exit_code = read_response(sock);
323→
324→	close(sock);
325→	return exit_code;
326→}
