4333→	/* This event is raised by the seat when a client provides a cursor image */
4334→	struct wlr_seat_pointer_request_set_cursor_event *event = data;
4335→	/* If we're "grabbing" the cursor, don't use the client's image, we will
4336→	 * restore it after "grabbing" sending a leave event, followed by a enter
4337→	 * event, which will result in the client requesting set the cursor surface */
4338→	if (cursor_mode != CurNormal && cursor_mode != CurPressed)
4339→		return;
4340→	/* This can be sent by any client, so we check to make sure this one
4341→	 * actually has pointer focus first. If so, we can tell the cursor to
4342→	 * use the provided surface as the cursor image. It will set the
4343→	 * hardware cursor on the output that it's currently on and continue to
4344→	 * do so as the cursor moves between outputs. */
4345→	if (event->seat_client == seat->pointer_state.focused_client)
4346→		wlr_cursor_set_surface(cursor, event->surface,
4347→				event->hotspot_x, event->hotspot_y);
4348→}
