			- titlebar_left - c->titlebar[CLIENT_TITLEBAR_RIGHT].size;
		int sh = c->geometry.height - 2 * c->bw
			- titlebar_top - c->titlebar[CLIENT_TITLEBAR_BOTTOM].size;
